node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Full user details
const user = db.prepare(\"SELECT * FROM users WHERE user_id = ?\").get('user_58b0a2d6');
console.log('=== USER DETAILS ===');
console.log(JSON.stringify(user, null, 2));

// Cart
const cart = db.prepare(\"SELECT * FROM carts WHERE customer_id = ?\").get('user_58b0a2d6');
console.log('\n=== CART ===');
console.log(JSON.stringify(cart, null, 2));

// Cart items
if (cart) {
  const cartItems = db.prepare(\"SELECT ci.*, p.name as product_name, p.price, p.current_price, p.category FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = ?\").all(cart.cart_id);
  console.log('\n=== CART ITEMS ===');
  console.log(JSON.stringify(cartItems, null, 2));
}

// Promotions
const promos = db.prepare(\"SELECT * FROM promotions\").all();
console.log('\n=== ALL PROMOTIONS ===');
console.log(JSON.stringify(promos, null, 2));

