console.log('\n=== ORDERS ===');
console.log(JSON.stringify(orders, null, 2));
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get current cart
const cart = db.prepare(\"SELECT * FROM carts WHERE customer_id = ?\").get('user_58b0a2d6');
const subtotal = cart.subtotal;

// Promo: 20% off, max \$50
const discountRaw = subtotal * 0.20;
const discount = Math.min(discountRaw, 50);
const newTotal = subtotal - discount + cart.gift_wrap_fee + cart.shipping_cost - cart.loyalty_discount;

// Apply promo
const appliedPromos = JSON.stringify(['PROMO0F1B01']);
db.prepare(\"UPDATE carts SET discount_amount = ?, total = ?, applied_promo_codes_json = ? WHERE cart_id = ?\")
  .run(discount, newTotal, appliedPromos, cart.cart_id);

// Verify
const updated = db.prepare(\"SELECT * FROM carts WHERE cart_id = ?\").get(cart.cart_id);
console.log('=== UPDATED CART ===');
console.log(JSON.stringify(updated, null, 2));
"
